func And(predicates ...predicate.AutomationScheduler) predicate.AutomationScheduler {
	return predicate.AutomationScheduler(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.AutomationScheduler) predicate.AutomationScheduler {
	return predicate.AutomationScheduler(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.AutomationScheduler) predicate.AutomationScheduler {
	return predicate.AutomationScheduler(sql.NotPredicates(p))
}
